package solution
import("regexp";"sort";"strings")
func SectionFlattening(s string)(string,bool){if s==""{return "",false};k:=regexp.MustCompile(`^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$`);d:=map[string]string{};for _,r:=range strings.Split(s,","){p:=strings.SplitN(r,"=",2);if len(p)!=2||p[1]==""{return "",false};q:=strings.Split(p[0],":");if len(q)!=2||!k.MatchString(q[0])||!k.MatchString(q[1]){return "",false};for _,c:=range []byte(p[1]){if c<32||c>126||c==','{return "",false}};id:=q[0]+"."+q[1];if _,ok:=d[id];ok{return "",false};d[id]=p[1]};keys:=[]string{};for x:=range d{keys=append(keys,x)};sort.Strings(keys);o:=[]string{};for _,x:=range keys{o=append(o,x+"="+d[x])};return strings.Join(o,","),true}
